 im=Image.open(path).convert('RGB');im.crop((2100,1020,3840,2050)).save(C/(name+'-detail.png'));im.crop((1250,780,2630,1320)).save(C/(name+'-arcade.png'));im.crop((2950,1450,3840,1920)).save(C/(name+'-soil.png'));im.crop((0,1550,1100,2300)).save(C/(name+'-dust.png')); im.resize((1920,1442),Image.Resampling.LANCZOS).save(C/(name+'-full.jpg'),quality=96)
